/**
 * emit to subscription queries of type FindDataPipeline,
 * but only if the id matches
 *
 * @param		entity	DataPipeline
 */
	protected void emitFindDataPipeline( DataPipeline entity ) {
		LOGGER.info("handling emitFindDataPipeline" );
		
	    queryUpdateEmitter.emit(FindDataPipelineQuery.class,
	                            query -> query.getFilter().getDataPipelineId().equals(entity.getDataPipelineId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDataPipeline
	 * 
	 * @param		entity	DataPipeline
	 */
	protected void emitFindAllDataPipeline( DataPipeline entity ) {
		LOGGER.info("handling emitFindAllDataPipeline" );
		
	    queryUpdateEmitter.emit(FindAllDataPipelineQuery.class,
	                            query -> true,
	                            entity);
	}

